@Service
@ConditionalOnProperty(name="weknora.knowledge.processing.enabled",havingValue="true")
public final class ChunkEditService {
  @FunctionalInterface public interface Embeddings {EmbeddingModel resolve(long owner,String model);}
  private final JdbcTemplate jdbc;private final ObjectMapper json;private final KnowledgeBaseWriteAuthorization writes;private final KnowledgeContentReadRepository projection;private final KnowledgeBaseCodec codec;private final KnowledgeTransferState transfer;private final KnowledgeSummaryRefresh refresh;private final Embeddings embeddings;private final DocumentProcessingHandler.Indexes indexes;private final TransactionTemplate tx;private final boolean pg;
  @org.springframework.beans.factory.annotation.Autowired
  public ChunkEditService(JdbcTemplate jdbc,ObjectMapper json,KnowledgeBaseWriteAuthorization writes,KnowledgeContentReadRepository projection,KnowledgeSummaryRefresh refresh,ModelClientFactory models,DocumentProcessingHandler.Indexes indexes,PlatformTransactionManager manager)throws java.io.IOException{this(jdbc,json,writes,projection,refresh,(owner,id)->models.embeddingForCleanup(new AuthContext("system-chunk",owner,"viewer",false,null,false,Set.of(),Set.of()),id),indexes,manager);}
  ChunkEditService(JdbcTemplate jdbc,ObjectMapper json,KnowledgeBaseWriteAuthorization writes,KnowledgeContentReadRepository projection,KnowledgeSummaryRefresh refresh,Embeddings embeddings,DocumentProcessingHandler.Indexes indexes,PlatformTransactionManager manager)throws java.io.IOException{this.jdbc=jdbc;this.json=json;this.writes=writes;this.projection=projection;this.refresh=refresh;this.embeddings=embeddings;this.indexes=indexes;codec=new KnowledgeBaseCodec(json);transfer=new KnowledgeTransferState(json);tx=new TransactionTemplate(manager);pg=jdbc.execute((org.springframework.jdbc.core.ConnectionCallback<Boolean>)c->c.getMetaData().getDatabaseProductName().equals("PostgreSQL"));}
  public KnowledgeBaseWriteAuthorization.WriteAccess authorize(AuthContext caller,String document,String raw,boolean revert){
    ChunkLifecycleService.capability(caller,"ingest");var docs=jdbc.queryForList("SELECT * FROM knowledges WHERE id=? AND deleted_at IS NULL",document);if(docs.isEmpty())throw api(404,1003,"Knowledge not found");
    return writes.authorizeChunkEdit(caller,text(docs.getFirst(),"knowledge_base_id"),raw,revert);
  }
  public void fetch(KnowledgeBaseWriteAuthorization.WriteAccess grant,String document,String id){if(document.isEmpty())throw api(400,1000,"Knowledge ID cannot be empty");if(id.isEmpty())throw api(400,1000,"Chunk ID cannot be empty");var row=chunk(grant.effectiveTenantId(),id,"Chunk not found",true);if(!text(row,"knowledge_id").equals(document))throw api(403,1002,"No permission to access this chunk");}
  public Map<String,Object> edit(KnowledgeBaseWriteAuthorization.WriteAccess grant,AuthContext actor,String document,String id,ChunkEditRequest request,String language,boolean revert){
    try {
      if(revert){var old=jdbc.queryForList("SELECT * FROM chunk_revisions WHERE tenant_id=? AND chunk_id=? AND revision=? ORDER BY id LIMIT 1",grant.effectiveTenantId(),id,request.revision());if(old.isEmpty())throw new IllegalStateException("record not found");request=new ChunkEditRequest(text(old.getFirst(),"content"),enabled(old.getFirst()),request.expected(),null);}
      var row=chunk(grant.effectiveTenantId(),id,"chunk not found",false);var doc=document(grant,row);if(!text(row,"chunk_type").equals("text"))throw new IllegalStateException("only text chunks can be edited");relations(row);
      if(request.expected()!=null&&request.expected()!=number(row,"content_revision"))throw conflict();
      String old=text(row,"content"),body=request.content()==null?old:KnowledgeUploadForms.goTrim(request.content());boolean oldEnabled=enabled(row),active=request.enabled()==null?oldEnabled:request.enabled();
      if(request.content()!=null){if(body.isEmpty())throw new IllegalStateException("chunk content cannot be empty");if(body.getBytes(StandardCharsets.UTF_8).length>200000)throw new IllegalStateException("chunk content exceeds 200000 bytes");}
      boolean changed=!body.equals(old),toggled=active!=oldEnabled;
      if(!changed&&!toggled){if(text(row,"index_status").equals("failed")){if(!text(row,"parent_chunk_id").isEmpty()&&number(row,"content_revision")>0)try{parent(row);}catch(Exception ignored){return response(row,document);}
          try{state(row,"processing");}catch(RuntimeException ignored){}try{sync(row);}catch(Exception failed){if(failed instanceof ApiException typed&&typed.status()==409)throw typed;try{state(row,"failed");}catch(RuntimeException ignored){}return response(row,document);}state(row,"ready");}return response(row,document);}
      String original=text(row,"source_content").isEmpty()?old:text(row,"source_content");if(request.content()!=null){var allowed=urls(original);for(String url:urls(body))if(!allowed.contains(url))throw new IllegalStateException("adding images to an existing chunk is not supported: "+url);}
      Object now=now();long revision=number(row,"content_revision");Object locators=changed?null:row.get("source_locators");
      tx.executeWithoutResult(status->{int count=jdbc.update("UPDATE chunks SET content=?,source_content=?,source_locators=?,content_revision=?,is_enabled=?,metadata="+(pg?"?::jsonb":"?")+",index_status='processing',last_editor_id=?,updated_at=? WHERE tenant_id=? AND id=? AND content_revision=? AND deleted_at IS NULL",IndexText.clean(body),IndexText.clean(original),locators,revision+1,active,row.get("metadata")==null?null:raw(row.get("metadata")),actor.userId(),now,grant.effectiveTenantId(),id,revision);if(count!=1)throw conflict();jdbc.update("INSERT INTO chunk_revisions(id,tenant_id,knowledge_base_id,knowledge_id,chunk_id,revision,content,is_enabled,editor_id,edit_source,edited_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,'user',?,?)",UUID.randomUUID().toString(),grant.effectiveTenantId(),text(row,"knowledge_base_id"),text(row,"knowledge_id"),id,revision,old,oldEnabled,text(row,"last_editor_id"),row.get("updated_at"),now);});
      row.put("source_content",original);row.put("source_locators",locators);row.put("content",body);row.put("content_revision",revision+1);row.put("is_enabled",active);row.put("last_editor_id",actor.userId());row.put("index_status","processing");row.put("updated_at",now);
      try{if(changed&&!text(row,"parent_chunk_id").isEmpty())parent(row);images(row);}catch(Exception failure){failed(row);return response(row,document);}
      if(refresh!=null)refresh.enqueue(grant.effectiveTenantId(),text(row,"knowledge_base_id"),document,text(doc,"summary_status"),language);
      try{sync(row);}catch(Exception failure){if(failure instanceof ApiException typed&&typed.status()==409)throw typed;failed(row);return response(row,document);}state(row,"ready");return response(row,document);
    }catch(ApiException typed){throw typed;}catch(Exception failure){throw api(revert?400:500,revert?1000:1007,diagnostic(failure));}
  }
  private Map<String,Object> document(KnowledgeBaseWriteAuthorization.WriteAccess grant,Map<String,Object> row){var docs=jdbc.queryForList("SELECT * FROM knowledges WHERE tenant_id=? AND id=? AND deleted_at IS NULL",grant.effectiveTenantId(),text(row,"knowledge_id"));if(docs.isEmpty())throw new IllegalStateException("knowledge not found");var doc=docs.getFirst();if(transfer.moving(doc.get("metadata")))throw api(409,1005,"knowledge has an unfinished move; retry the move first");var kb=base(text(doc,"knowledge_base_id"));if(number(kb,"tenant_id")!=number(doc,"tenant_id")||!text(doc,"knowledge_base_id").equals(grant.knowledgeBaseId()))throw api(403,1002,"knowledge does not belong to its knowledge base");if(!text(row,"knowledge_base_id").equals(text(doc,"knowledge_base_id")))throw api(403,1002,"chunk does not belong to its knowledge base");return doc;}
  private void relations(Map<String,Object> row){var parents=new ArrayList<Map<String,Object>>();parents.add(row);if(!text(row,"parent_chunk_id").isEmpty()){var parent=chunk(number(row,"tenant_id"),text(row,"parent_chunk_id"),"chunk not found",false);if(!same(row,parent))throw api(403,1002,"parent chunk does not belong to its document");parents.add(parent);}for(var parent:parents)for(var child:children(parent))if(!same(row,child))throw api(403,1002,"child chunk does not belong to its document");}
  private boolean same(Map<String,Object> a,Map<String,Object> b){return number(a,"tenant_id")==number(b,"tenant_id")&&text(a,"knowledge_id").equals(text(b,"knowledge_id"))&&text(a,"knowledge_base_id").equals(text(b,"knowledge_base_id"));}
  private Map<String,Object> chunk(long owner,String id,String missing,boolean publicLookup){var rows=jdbc.queryForList("SELECT * FROM chunks WHERE tenant_id=? AND id=? AND deleted_at IS NULL",owner,id);if(rows.isEmpty()){if(publicLookup)throw api(404,1003,missing);throw new IllegalStateException(missing);}return new LinkedHashMap<>(rows.getFirst());}
  private List<Map<String,Object>> children(Map<String,Object> row){return jdbc.queryForList("SELECT * FROM chunks WHERE tenant_id=? AND parent_chunk_id=? AND deleted_at IS NULL ORDER BY chunk_index",number(row,"tenant_id"),text(row,"id"));}
  private Map<String,Object> base(String id){var rows=jdbc.queryForList("SELECT * FROM knowledge_bases WHERE id=? AND deleted_at IS NULL",id);if(rows.isEmpty())throw new IllegalStateException("knowledge base not found");return rows.getFirst();}
  Map<String,Object> writableQuestion(KnowledgeBaseWriteAuthorization.WriteAccess grant,String id){var row=chunk(grant.effectiveTenantId(),id,"chunk not found",false);var docs=jdbc.queryForList("SELECT knowledge_base_id FROM knowledges WHERE tenant_id=? AND id=? AND deleted_at IS NULL",grant.effectiveTenantId(),text(row,"knowledge_id"));if(!docs.isEmpty()&&!text(docs.getFirst(),"knowledge_base_id").equals(grant.knowledgeBaseId()))throw api(403,1002,"无权修改该知识库");document(grant,row);return row;}
  JsonNode questionMetadata(Map<String,Object> row)throws Exception{return metadata(row);}
  void reindexQuestion(Map<String,Object> row)throws Exception{sync(row);}
  void reindexRegeneratedQuestion(Map<String,Object> row,Runnable guard)throws Exception{sync(row,guard);}
  void deleteQuestionIndex(Map<String,Object> row,String questionId)throws Exception{
    var config=new LinkedHashMap<>(base(text(row,"knowledge_base_id")));config.remove("indexing_strategy");var kb=codec.fromRow(config);long owner=number(row,"tenant_id");IndexWriter writer;
    try{writer=indexes.resolve(owner,kb);}catch(Exception failure){throw new IllegalStateException("failed to create retrieve engine: "+diagnostic(failure),failure);}
    EmbeddingModel model;try{model=embeddings.resolve(owner,kb.path("embedding_model_id").asText());}catch(Exception failure){throw new IllegalStateException("failed to get embedding model: "+modelDiagnostic(failure),failure);}
    // Go treats a missing/failed individual physical delete as best effort, but model resolution is required.
    try{writer.prepare(Set.of(model.dimensions()));transaction(writer,c->writer.deleteBySource(c,List.of(QuestionGenerationText.sourceId(text(row,"id"),questionId))));}catch(Exception ignored){}
  }
  private void images(Map<String,Object> row)throws Exception {var visible=urls(text(row,"content"));for(var child:children(row)){if(!Set.of("image_caption","image_ocr").contains(text(child,"chunk_type")))continue;boolean active=enabled(row)&&imageUrls(text(child,"image_info")).stream().anyMatch(visible::contains);if(enabled(child)==active&&text(child,"index_status").equals("ready"))continue;jdbc.update("UPDATE chunks SET is_enabled=?,index_status='processing',updated_at=? WHERE tenant_id=? AND id=? AND content_revision=? AND deleted_at IS NULL",active,now(),number(child,"tenant_id"),text(child,"id"),number(child,"content_revision"));child.put("is_enabled",active);state(child,"processing");try{sync(child);}catch(Exception failure){failed(child);throw failure;}state(child,"ready");}}
  private void sync(Map<String,Object> row)throws Exception {sync(row,null);}
  private void sync(Map<String,Object> row,Runnable guard)throws Exception {
    if(guard!=null)guard.run();
    var storedBase=base(text(row,"knowledge_base_id"));var configBase=new LinkedHashMap<>(storedBase);configBase.remove("indexing_strategy");var kb=codec.fromRow(configBase);var strategy=indexing(storedBase.get("indexing_strategy"));if(guard!=null&&!KnowledgeBaseCodec.hasAnyIndexing(strategy))strategy=json.createObjectNode().put("vector_enabled",true).put("keyword_enabled",true).put("graph_enabled",false).put("wiki_enabled",false);kb.set("indexing_strategy",strategy);if(!strategy.path("vector_enabled").asBoolean()&&!strategy.path("keyword_enabled").asBoolean())return;
    long owner=number(row,"tenant_id");var model=embeddings.resolve(owner,kb.path("embedding_model_id").asText());var writer=indexes.resolve(owner,kb);writer.prepare(Set.of(model.dimensions()));transaction(writer,c->writer.deleteByChunk(c,List.of(text(row,"id"))));if(!enabled(row))return;
    var docs=jdbc.queryForList("SELECT * FROM knowledges WHERE tenant_id=? AND id=? AND deleted_at IS NULL",owner,text(row,"knowledge_id"));if(docs.isEmpty())throw new IllegalStateException("knowledge not found");String sourceTitle=text(docs.getFirst(),"title"),title=KnowledgeUploadForms.goTrim(sourceTitle),content=KnowledgeUploadForms.goTrim(text(row,"content"));if(!text(row,"context_header").isEmpty())content=text(row,"context_header")+"\n\n"+content;
    var entries=new LinkedHashMap<String,IndexEntry>();entry(entries,row,text(row,"id"),title,content);for(JsonNode q:metadata(row).path("generated_questions"))if(!KnowledgeUploadForms.goTrim(q.path("question").asText()).isEmpty())entry(entries,row,QuestionGenerationText.sourceId(text(row,"id"),q.path("id").asText()),title,q.path("question").asText());
    binding(row,kb,sourceTitle);if(guard!=null)guard.run();var list=new ArrayList<>(entries.values());float[][] values=null;try(var call=new CallContext()){for(int attempt=0;attempt<5;attempt++)try{values=model.embed(call,list.stream().map(e->IndexText.embeddingInput(e.content())).toList(),false);break;}catch(RuntimeException failure){binding(row,kb,sourceTitle);if(guard!=null)guard.run();if(attempt==4)throw failure;call.pause(Duration.ofMillis(200L<<attempt));}}
    binding(row,kb,sourceTitle);if(guard!=null)guard.run();if(values==null||values.length!=list.size())throw new IllegalStateException("embedding count mismatch");var vectors=new LinkedHashMap<String,float[]>();for(int i=0;i<list.size();i++){FloatVectors.validate(values[i],model.dimensions());vectors.put(list.get(i).sourceId(),values[i]);}transaction(writer,c->{binding(row,kb,sourceTitle);if(guard!=null)guard.run();writer.batchSave(c,list,vectors);});
  }
  private JsonNode indexing(Object stored){
    var defaults=json.createObjectNode().put("vector_enabled",true).put("keyword_enabled",true).put("wiki_enabled",false).put("graph_enabled",false);
    // Go's sql.Scanner accepts []byte; SQLite TEXT values take its legacy default branch.
    if(stored==null||!pg&&stored instanceof String)return defaults;
    var schema=struct("IndexingStrategy","types.IndexingStrategy");for(String field:List.of("vector_enabled","keyword_enabled","wiki_enabled","graph_enabled"))field(schema,field,primitive("bool"));
    try{return new GoUploadJson(json).decode(raw(stored),schema);}catch(Exception invalid){return defaults;}
  }
  private void entry(Map<String,IndexEntry> entries,Map<String,Object> row,String id,String title,String content){entries.putIfAbsent(id,new IndexEntry(id,0,text(row,"id"),text(row,"knowledge_id"),text(row,"knowledge_base_id"),"",title.isEmpty()?content:title+"\n"+content,true));}
  private JsonNode metadata(Map<String,Object> row)throws Exception {
    String raw=raw(row.get("metadata"));if(raw.isEmpty())return json.createObjectNode();
    var schema=struct("DocumentChunkMetadata","types.DocumentChunkMetadata");var question=struct("GeneratedQuestion","types.GeneratedQuestion");
    field(question,"id",primitive("string"));field(question,"question",primitive("string"));field(question,"content_revision",json.createObjectNode().put("kind","pointer").put("type","*int").set("elem",primitive("int")));
    field(schema,"generated_questions",json.createObjectNode().put("kind","slice").put("type","[]types.GeneratedQuestion").set("elem",question));field(schema,"generated_questions_revision",primitive("int"));
    return new GoUploadJson(json).decode(raw,schema);
  }
  private com.fasterxml.jackson.databind.node.ObjectNode struct(String name,String type){var node=json.createObjectNode().put("kind","struct").put("name",name).put("type",type);node.putArray("fields");return node;}
  private JsonNode primitive(String type){return json.createObjectNode().put("kind",type).put("type",type);}
  private void field(com.fasterxml.jackson.databind.node.ObjectNode schema,String name,JsonNode type){((com.fasterxml.jackson.databind.node.ArrayNode)schema.get("fields")).add(json.createObjectNode().put("name",name).set("schema",type));}
  @FunctionalInterface private interface Mutation{void run(java.sql.Connection connection)throws Exception;}
  private void transaction(IndexWriter writer,Mutation mutation){tx.executeWithoutResult(status->jdbc.execute((org.springframework.jdbc.core.ConnectionCallback<Void>)connection->{try{mutation.run(connection);return null;}catch(java.sql.SQLException failure){throw failure;}catch(RuntimeException failure){throw failure;}catch(Exception failure){throw new java.sql.SQLException(failure);}}));}
  private void state(Map<String,Object> row,String status){row.put("index_status",status);row.put("updated_at",now());int count=jdbc.update("UPDATE chunks SET index_status=?,updated_at=? WHERE tenant_id=? AND id=? AND content_revision=? AND content=? AND is_enabled=? AND COALESCE(CAST(metadata AS TEXT),'')=? AND deleted_at IS NULL AND EXISTS(SELECT 1 FROM knowledges k JOIN knowledge_bases b ON b.id=k.knowledge_base_id WHERE k.id=chunks.knowledge_id AND k.tenant_id=chunks.tenant_id AND b.tenant_id=chunks.tenant_id AND k.knowledge_base_id=chunks.knowledge_base_id AND k.deleted_at IS NULL AND b.deleted_at IS NULL)",status,row.get("updated_at"),number(row,"tenant_id"),text(row,"id"),number(row,"content_revision"),IndexText.clean(text(row,"content")),enabled(row),raw(row.get("metadata")));if(count!=1)throw conflict();}
  private void binding(Map<String,Object> expected,JsonNode kb,String title){
    var rows=jdbc.queryForList("SELECT * FROM chunks WHERE tenant_id=? AND id=? AND deleted_at IS NULL",number(expected,"tenant_id"),text(expected,"id"));if(rows.isEmpty())throw conflict();var current=rows.getFirst();for(String field:List.of("knowledge_id","knowledge_base_id","context_header","parent_chunk_id"))if(!text(current,field).equals(text(expected,field)))throw conflict();if(number(current,"content_revision")!=number(expected,"content_revision")||!text(current,"content").equals(IndexText.clean(text(expected,"content")))||enabled(current)!=enabled(expected)||!sameMetadata(current.get("metadata"),expected.get("metadata")))throw conflict();
    var docs=jdbc.queryForList("SELECT * FROM knowledges WHERE tenant_id=? AND id=? AND deleted_at IS NULL",number(expected,"tenant_id"),text(expected,"knowledge_id"));if(docs.isEmpty()||!text(docs.getFirst(),"knowledge_base_id").equals(text(expected,"knowledge_base_id"))||!text(docs.getFirst(),"title").equals(title))throw conflict();var bases=jdbc.queryForList("SELECT * FROM knowledge_bases WHERE tenant_id=? AND id=? AND deleted_at IS NULL",number(expected,"tenant_id"),text(expected,"knowledge_base_id"));if(bases.isEmpty())throw conflict();var base=bases.getFirst();for(String field:List.of("embedding_model_id","type","vector_store_id"))if(!text(base,field).equals(kb.path(field).asText("")))throw conflict();
  }

  private boolean sameMetadata(Object a,Object b){String left=raw(a),right=raw(b);if(left.equals(right))return true;try{return json.readTree(left).equals(json.readTree(right));}catch(Exception invalid){return false;}}
  private void failed(Map<String,Object> row){try{state(row,"failed");}catch(RuntimeException ignored){}}
  private record Replacement(int start,int end,String content,Instant updated){}
  private void parent(Map<String,Object> edited){var row=chunk(number(edited,"tenant_id"),text(edited,"parent_chunk_id"),"chunk not found",false);String original=text(row,"source_content").isEmpty()?text(row,"content"):text(row,"source_content");int[] source=original.codePoints().toArray();var replacements=new ArrayList<Replacement>();for(var child:children(row)){int start=(int)(number(child,"start_at")-number(row,"start_at")),end=(int)(number(child,"end_at")-number(row,"start_at"));if(number(child,"content_revision")!=0&&start>=0&&end>=start&&end<=source.length)replacements.add(new Replacement(start,end,text(child,"content"),Instant.parse(KnowledgeBaseRepository.timestamp(child.get("updated_at")))));}
    replacements.sort(Comparator.comparing(Replacement::updated).reversed());var selected=new ArrayList<Replacement>();var conflicts=new ArrayList<Replacement>();for(var candidate:replacements){boolean overlap=selected.stream().anyMatch(old->candidate.start()<old.end()&&candidate.end()>old.start());(overlap?conflicts:selected).add(candidate);}selected.sort(Comparator.comparingInt(Replacement::start).reversed());String value=original;for(var replacement:selected){int start=value.offsetByCodePoints(0,replacement.start()),end=value.offsetByCodePoints(0,replacement.end());value=value.substring(0,start)+replacement.content()+value.substring(end);}for(var replacement:conflicts)value=join(value,replacement.content());row.put("content",value);row.put("source_content",original);row.put("source_locators",null);row.put("updated_at",now());jdbc.update("UPDATE chunks SET content=?,source_content=?,source_locators=NULL,parent_chunk_id=?,updated_at=? WHERE tenant_id=? AND id=? AND deleted_at IS NULL",IndexText.clean(value),IndexText.clean(original),text(row,"parent_chunk_id"),row.get("updated_at"),number(row,"tenant_id"),text(row,"id"));}
  static String join(String a,String b){if(a.isEmpty())return b;if(b.isEmpty()||a.equals(b)||b.codePointCount(0,b.length())>=12&&a.contains(b))return a;if(a.codePointCount(0,a.length())>=12&&b.contains(a))return b;for(int n=Math.min(400,Math.min(a.codePointCount(0,a.length()),b.codePointCount(0,b.length())));n>=12;n--)if(a.substring(a.offsetByCodePoints(0,a.codePointCount(0,a.length())-n)).equals(b.substring(0,b.offsetByCodePoints(0,n))))return a+b.substring(b.offsetByCodePoints(0,n));return a+"\n\n"+b;}
  static Set<String> urls(String content){var out=new LinkedHashSet<String>();var markdown=Pattern.compile("!\\[([^\\]]*)\\]\\(([^)]+)\\)").matcher(content);while(markdown.find())out.add(markdown.group(2));var html=Pattern.compile("<img\\b([^>]*?)\\ssrc\\s*=\\s*['\"]([^'\"]+)['\"]([^>]*)>",Pattern.CASE_INSENSITIVE).matcher(content);while(html.find()){String url=KnowledgeUploadForms.goTrim(html.group(2));if(!url.isEmpty())out.add(url);}return out;}
  private Set<String> imageUrls(String raw){var out=new HashSet<String>();try{
    var schema=struct("ImageInfo","types.ImageInfo");for(String field:List.of("sha256","url","original_url","caption","ocr_text"))field(schema,field,primitive("string"));for(String field:List.of("start_pos","end_pos"))field(schema,field,primitive("int"));
    var attrs=struct("ImageAttrs","types.ImageAttrs");field(attrs,"schema",primitive("string"));var source=struct("ImageAttrSource","types.ImageAttrSource");field(source,"schema",primitive("string"));field(source,"prompt",primitive("string"));field(source,"custom",primitive("bool"));field(attrs,"source",source);field(schema,"attrs",attrs);
    var array=new GoUploadJson(json).decode(raw,json.createObjectNode().put("kind","slice").put("type","[]types.ImageInfo").set("elem",schema));
    for(var image:array)for(String key:List.of("url","original_url"))if(!image.path(key).asText().isEmpty())out.add(image.path(key).asText());
  }catch(Exception ignored){}return out;}

  private Map<String,Object> response(Map<String,Object> row,String document){var result=new LinkedHashMap<String,Object>();result.put("success",true);result.put("data",projection.projectChunk(row));try{var docs=jdbc.queryForList("SELECT summary_status,description FROM knowledges WHERE tenant_id=? AND id=? AND deleted_at IS NULL",number(row,"tenant_id"),document);if(!docs.isEmpty()){result.put("summary_status",text(docs.getFirst(),"summary_status"));result.put("description",text(docs.getFirst(),"description"));}}catch(RuntimeException ignored){}return result;}
  private Object now(){return pg?Timestamp.from(Instant.now()):Instant.now().toString();}
  private static long number(Map<String,Object> row,String field){return row.get(field) instanceof Number n?n.longValue():0;}
  private static String text(Map<String,Object> row,String field){return Objects.toString(row.get(field),"");}
  private static String raw(Object value){return value instanceof byte[] bytes?new String(bytes,StandardCharsets.UTF_8):Objects.toString(value,"");}
  private static boolean enabled(Map<String,Object> row){return row.get("is_enabled") instanceof Boolean b?b:Objects.toString(row.get("is_enabled"),"").matches("(?i)true|1");}
  private static ApiException conflict(){return api(409,1005,"Chunk was modified by another user; refresh and retry");}
  private static ApiException api(int status,int code,String message){return new ApiException(status,status==403?"FORBIDDEN":status==404?"NOT_FOUND":status==409?"CONFLICT":status==400?"BAD_REQUEST":"INTERNAL_SERVER_ERROR",message).withAppCode(code);}
  static String modelDiagnostic(Exception failure){return failure instanceof ApiException api&&api.appCode()==null&&api.code().equals("NOT_FOUND")&&api.getMessage().equals("Model not found")?"model not found":diagnostic(failure);}
  static String diagnostic(Exception failure){Throwable cause=failure;while(cause.getCause()!=null)cause=cause.getCause();if(cause instanceof org.postgresql.util.PSQLException pg&&pg.getServerErrorMessage()!=null)return pg.getServerErrorMessage().getSeverity()+": "+pg.getServerErrorMessage().getMessage()+" (SQLSTATE "+pg.getSQLState()+")";String message=Objects.toString(cause.getMessage(),"Internal server error");if(message.startsWith("[SQLITE_")&&message.endsWith(")")){int open=message.indexOf(" (");if(open>=0)return message.substring(open+2,message.length()-1);}return message;}
}
